Opening javascript:(function(){
  const canvas = document.querySelector('canvas.interactive') || document.querySelector('canvas');
  if (!canvas) return;

  function fire(type, x, y, buttons) {
    const evt = new PointerEvent(type, {
      clientX: x,
      clientY: y,
      bubbles: true,
      cancelable: true,
      view: window,
      buttons: buttons,
      pressure: buttons ? 0.5 : 0
    });
    canvas.dispatchEvent(evt);
  }

  // Draw rectangle
  const rectBtn = document.querySelector('button[aria-label="Rectangle"]') || Array.from(document.querySelectorAll('button')).find(b => b.title && b.title.includes('Rectangle'));
  if (rectBtn) rectBtn.click();

  setTimeout(() => {
    // Drag rectangle from (300, 200) to (600, 450)
    fire('pointerdown', 300, 200, 1);
    fire('pointermove', 450, 325, 1);
    fire('pointermove', 600, 450, 1);
    fire('pointerup', 600, 450, 0);

    setTimeout(() => {
      // Draw ellipse
      const ellipseBtn = document.querySelector('button[aria-label="Ellipse"]') || Array.from(document.querySelectorAll('button')).find(b => b.title && b.title.includes('Ellipse'));
      if (ellipseBtn) ellipseBtn.click();

      setTimeout(() => {
        // Drag ellipse completely inside: (350, 250) to (550, 400)
        fire('pointerdown', 350, 250, 1);
        fire('pointermove', 450, 325, 1);
        fire('pointermove', 550, 400, 1);
        fire('pointerup', 550, 400, 0);
      }, 200);
    }, 200);
  }, 200);
})()
